reference_solution:
def format_license_key(s,k):
    clean=s.replace('-','').upper()
    if not clean:
        return ''
    first=len(clean)%k or k
    groups=[clean[:first]]
    groups.extend(clean[i:i+k] for i in range(first,len(clean),k))
    return '-'.join(groups)

